#Requires -Version 5.1
# fix-rrhh-modal-vista.ps1
# En lugar de navegar a una pagina nueva (que colgaba),
# al pinchar en un trabajador se abre un modal en modo lectura
# con dos pestanas: Detalle y Asignaciones.
# El boton Editar en el modal abre el formulario de edicion existente.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> fix: RRHH modal vista" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("viewRecord")) { Write-Host "  OK: estado viewRecord" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("Modal de vista")) { Write-Host "  OK: modal de vista" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("fetchAsignaciones")) { Write-Host "  OK: carga asignaciones" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add src\app\maestros\recursos-humanos\page.tsx"
Write-Host '  git commit -m "fix: RRHH ficha como modal con pestanas Detalle y Asignaciones"'
Write-Host "  git push"
